def get_did_deactivation_notice(
    self,
    tenant_id: str,
    did: str,
) -> Optional[DidDeactivationNoticeRecord]:
    """只读查询本租户某 DID 的外部停用通告；未登记（含他租户）返回
    None。不写状态、不记审计。"""
    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        row = (
            bucket.get("did_deactivation_notices", {}).get(did)
